    /// <summary>
    /// Creates a <see cref="WebApplicationBuilder"/> and configures logging, configuration
    /// database, and optionally the Bovis data source.
    /// </summary>
    /// <param name="args">Command‑line arguments passed to the builder.</param>
    /// <param name="setupDatabase">If true, also configures the Bovis database connection.</param>
    /// <returns>A fully configured <see cref="WebApplicationBuilder"/> instance.</returns>
    public static WebApplicationBuilder CreateAndSetupBuilder(string[] args, bool setupDatabase = false)
    {
        {
            // Force loading Bovis.Services
            var p = new Bovis.Services.MarkdownString();
        }

        var builder = WebApplication.CreateBuilder(args);
        builder.Configuration.AddEnvironmentVariables();
        // local local.json config
        var basePath = System.AppContext.BaseDirectory;
        LoadJsonFromDir(builder.Configuration, basePath);

        var bovis_config_dir = Environment.GetEnvironmentVariable("BOVIS_CONFIG_DIR");
        if (bovis_config_dir != null)
        {
            LoadJsonAllJsonFromDir(builder.Configuration, bovis_config_dir);
        }

        using var configurableBinder = new Bovis.Interfaces.Configuration.ConfigurableBinder(builder.Configuration);

        Logging.Logger.SetupLogging(builder.Configuration);
        Logging.Logger.Info($"BC78B368D86I Application base path {basePath}. This is where I load files and assemblies from.");
        Logging.Logger.Info($"BC4AC6E5659I Current working directory is {System.IO.Directory.GetCurrentDirectory()}.");

        builder.Services.AddSingleton<ILogger>(Bovis.Logging.Logger.Default);
        // Add services to the container.

        builder.Services.AddLogging(b =>
        {
            b.ClearProviders();
            b.AddProvider(new Bovis.Logging.LoggingProvider());
        }
        );
        //========== Setup Configuration Database
        // DevConnectionString override everything
        var configUrl = builder.Configuration.GetSection("DevConnectionStrings")["ConfigConnection"]
            ?? builder.Configuration.GetConnectionString("ConfigConnection")
            ?? throw new InvalidOperationException("BC73A7AEAFE Connection string 'ConfigConnection' not found.");

        // Open the configuration database and set it as default.
        Bovis.Logging.Logger.Default.LogInformation("BC52350607CI Open configuration database '{configUrl}'", configUrl);
        var configStore = Bovis.Storage.Storage.OpenStorageUrl(configUrl, true);
        configStore.AddConfiguration(builder.Configuration);
        builder.Services.AddSingleton<IConfigurationStore>(configStore);

        //========== Setup Bovis Database
        if (setupDatabase)
        {
            // Well this could be done better. 
            // We want to be flexible with DataConnection and DataConnectionInit 
            // So we have three sources of truth here: 
            // DevConnectionStrings/DataConnection from json -- this is a override for development
            // ConnectionStrings.DataConnection from db      -- the right place, in the configuration database
            // ConnectionStrings/DataConnection from json    -- default value as a fallback.
            // DataConnectionInit is an initial command isseud to the DataConnection database after opening. 
            // Ususally this contains a statement to setup the right schema for the session and it means 
            // we use it with the DataConnection from the same source. 
            // So we read DataConnection and DataConnectionInit and ignore DataConnectionInit if it's from a different source.
            Bovis.Logging.Logger.Default.LogInformation("BC130680200I setting up Bovis database connection");
            // read data connection. 
            // Priority is 
            int dataUrlSrc = 0;
            var dataUrl = builder.Configuration.GetSection("DevConnectionStrings")["DataConnection"];
            if (dataUrl != null) { dataUrlSrc = 1; goto found; }
            dataUrl = configStore.GetProperty("ConnectionStrings.DataConnection");
            if (dataUrl != null) { dataUrlSrc = 2; goto found; }
            dataUrl = builder.Configuration.GetConnectionString("DataConnection");
            if (dataUrl != null) { dataUrlSrc = 3; goto found; }
            throw new InvalidOperationException("BC25F86C3E3E Connection string 'DataConnection' not found.");
        found:
            Bovis.Logging.Logger.Default.LogInformation("BC966B3E63CI Found Bovis connection string {dataUrl}", dataUrl);
            int dataInitSrc = 0;
            var dataInit = builder.Configuration.GetSection("DevConnectionStrings")["DataConnectionInit"];
            if (dataInit != null) { dataInitSrc = 1; goto found2; }
            dataInit = configStore.GetProperty("ConnectionStrings.DataConnectionInit");
            if (dataInit != null) { dataInitSrc = 2; goto found2; }
            dataInit = builder.Configuration.GetConnectionString("DataConnectionInit");
            if (dataInit != null) { dataInitSrc = 3; goto found2; }
        found2:
            // If the sources differ, ignore the init command to avoid mismatched setups.
            if (dataUrlSrc != dataInitSrc) dataInit = null;
            var dbConnection = new ConnectionUrl(dataUrl).CreateConnection();

            if (builder.Configuration.GetConnectionString("DataConnectionWrapper") is string s)
                if (s == "LoggingDbConnection")
                {
                    dbConnection = new Util.LoggingDbConnection(dbConnection, Bovis.Logging.Logger.Make("LoggingDb"));
                }

            var backend = configStore.GetProperty("ConnectionStrings.DataBackend");
